    if l.strip():
        p=l.split(); syms.append(p[0]); X.append(list(map(float,p[1:4])))
X=np.array(X); N=len(syms)
print("n atoms",N)
d=lambda i,j: round(float(np.linalg.norm(X[i]-X[j])),2)
print("Ir-Zn",d(0,1),"Ir-P",d(0,3),"Ir-Hu",d(0,2),"Zn-Hu",d(1,2),"Ir-H",d(0,4),d(0,5),"Zn-C",d(1,6),"Ir-C2",d(0,25),d(0,90))
bonds=[tuple(map(int,l.split())) for l in open('bonds.txt') if l.split()]
bs=set(bonds)
adj=[set() for _ in range(N)]
for a,b in bonds: adj[a].add(b); adj[b].add(a)
excl=set(bs)
for c in range(N):
    for a in adj[c]:
        for b in adj[c]:
            if a<b: excl.add((a,b))
pr=[]
for i,j in itertools.combinations(range(N),2):
    if (i,j) in bs or (i,j) in excl: continue
    pr.append((np.linalg.norm(X[i]-X[j]),i,syms[i],j,syms[j]))
